 $state=bin2hex(random_bytes(32));$_SESSION['passenger_facebook_oauth_state']=$state;$_SESSION['passenger_facebook_oauth_started']=time();unset($_SESSION['passenger_facebook_booking']);
 $slug=trim((string)($_GET['slug']??''));$token=trim((string)($_GET['token']??''));if($slug!==''&&preg_match('/^[a-f0-9]{64}$/',$token)){$q=$db->prepare("SELECT tp.id,tp.passenger_profile_id,tp.organization_id,t.slug FROM tour_passengers tp JOIN tours t ON t.id=tp.tour_id JOIN organizations o ON o.id=t.organization_id WHERE t.slug=? AND tp.booking_access_token_hash=? AND tp.booking_access_token_revoked_at IS NULL AND tp.status='ACTIVE' AND o.status='ACTIVE' LIMIT 1");$q->execute([$slug,hash('sha256',$token)]);if($b=$q->fetch())$_SESSION['passenger_facebook_booking']=['tp_id'=>(int)$b['id'],'profile_id'=>(int)$b['passenger_profile_id'],'organization_id'=>(int)$b['organization_id'],'slug'=>$b['slug']];}
