$db->beginTransaction();$q=$db->prepare("SELECT pa.id,pa.organization_id,pa.passenger_profile_id,pa.email,pa.status FROM passenger_auth_identities i JOIN passenger_accounts pa ON pa.id=i.passenger_account_id WHERE i.provider='FACEBOOK' AND i.provider_subject=? LIMIT 2 FOR UPDATE");$q->execute([$subject]);$irs=$q->fetchAll();if(count($irs)>1)throw new RuntimeException('This Facebook identity is linked more than once. Contact the organizer.');$account=null;
if($irs){$account=$irs[0];if($account['status']!=='ACTIVE')throw new RuntimeException('This passenger account is not active.');if(strtolower((string)$account['email'])!==$email)throw new RuntimeException('Facebook email does not match the linked account.');}
elseif($booking){$q=$db->prepare("SELECT pa.id,pa.organization_id,pa.passenger_profile_id,pa.email,pa.status FROM passenger_accounts pa WHERE pa.organization_id=? AND pa.passenger_profile_id=? LIMIT 1 FOR UPDATE");$q->execute([$booking['organization_id'],$booking['profile_id']]);$account=$q->fetch()?:null;if($account&&$account['status']!=='ACTIVE')throw new RuntimeException('The passenger account is not active.');if($account&&strtolower((string)$account['email'])!==$email)throw new RuntimeException('This Facebook email does not match the passenger profile email.');if(!$account){$q=$db->prepare("SELECT id FROM passenger_accounts WHERE organization_id=? AND LOWER(email)=LOWER(?) LIMIT 1 FOR UPDATE");$q->execute([$booking['organization_id'],$email]);if($q->fetch())throw new RuntimeException('This email already belongs to another passenger account in this organization.');$hash=password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT);$q=$db->prepare("INSERT INTO passenger_accounts(organization_id,passenger_profile_id,email,password_hash,status,email_verified_at) VALUES(?,?,?,?, 'ACTIVE',NOW())");$q->execute([$booking['organization_id'],$booking['profile_id'],$email,$hash]);$account=['id'=>(int)$db->lastInsertId(),'organization_id'=>$booking['organization_id'],'passenger_profile_id'=>$booking['profile_id'],'email'=>$email,'status'=>'ACTIVE'];}}
else{$q=$db->prepare("SELECT pa.id,pa.organization_id,pa.passenger_profile_id,pa.email,pa.status FROM passenger_accounts pa WHERE LOWER(pa.email)=LOWER(?) LIMIT 2 FOR UPDATE");$q->execute([$email]);$rows=$q->fetchAll();if(count($rows)!==1)throw new RuntimeException('We could not uniquely identify your passenger account. Open your tour booking link first, or contact the organizer.');$account=$rows[0];if($account['status']!=='ACTIVE')throw new RuntimeException('This passenger account is not active.');}
