$q=$db->prepare("SELECT id FROM passenger_auth_identities WHERE passenger_account_id=? AND provider='FACEBOOK' LIMIT 1 FOR UPDATE");$q->execute([(int)$account['id']]);$existing=$q->fetchColumn();if($existing){$q=$db->prepare("UPDATE passenger_auth_identities SET provider_subject=?,provider_email=?,last_login_at=NOW() WHERE id=?");$q->execute([$subject,$email,(int)$existing]);}else{$q=$db->prepare("SELECT id FROM passenger_auth_identities WHERE provider='FACEBOOK' AND provider_subject=? LIMIT 1 FOR UPDATE");$q->execute([$subject]);if($q->fetch())throw new RuntimeException('This Facebook account is already linked to another passenger.');$q=$db->prepare("INSERT INTO passenger_auth_identities(passenger_account_id,provider,provider_subject,provider_email,last_login_at) VALUES(?, 'FACEBOOK',?,?,NOW())");$q->execute([(int)$account['id'],$subject,$email]);}$q=$db->prepare('UPDATE passenger_accounts SET last_login_at=NOW(),email_verified_at=COALESCE(email_verified_at,NOW()) WHERE id=?');$q->execute([(int)$account['id']]);$db->commit();passenger_oauth_rate_success();session_regenerate_id(true);$_SESSION['passenger_account_id']=(int)$account['id'];$_SESSION['passenger_profile_id']=(int)$va['passenger_profile_id'];$_SESSION['passenger_organization_id']=(int)$va['organization_id'];saas_redirect('passenger_dashboard.php');
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();passenger_oauth_rate_fail();fb_fail($e->getMessage());}
